mapper.delete:
DELETE FROM chat_messages
WHERE created_at <= #{before}
AND session_id IN (SELECT id FROM chat_sessions WHERE user_id = #{userId})
LIMIT #{limit}

mapper.select:
SELECT m.*
FROM chat_messages m
JOIN chat_sessions s ON s.id = m.session_id
WHERE s.user_id = #{userId}
AND m.favorite = 1

  AND m.session_id = #{sessionId}


  AND m.content LIKE CONCAT('%', #{keyword}, '%')

ORDER BY m.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM chat_messages m JOIN chat_sessions s ON s.id = m.session_id WHERE s.user_id = #{userId} AND m.favorite = 1
AND m.session_id = #{sessionId}
AND m.content LIKE CONCAT('%', #{keyword}, '%')
